function groupByBlock(type, part, qs) {
  const names = ((Q_BLOCKS[type] || {})[part]) || {};
  const out = [];
  qs.forEach(q => {
    const key = q.b && names[q.b] ? q.b : '_';
    let g = out.find(x => x.key === key);
    if (!g) { g = {key, ...(names[key] || {name: Object.keys(names).length ? 'Дополнительно' : '', emo: '', about: ''}), qs: []}; out.push(g); }
    g.qs.push(q);
  });
  return out;
}

