/* [город как пишем, страна] или null, если город незнакомый */
function cityCountry(city) { return CITY_COUNTRY.map[CITY_COUNTRY.norm(city)] || null; }
/* подсказки при вводе города: до limit совпадений по началу слова */
function citySuggest(text, limit = 4) {
  const t = CITY_COUNTRY.norm(text);
  if (t.length < 2) return [];
  const seen = new Set(), out = [];
  const add = test => { for (const [k, v] of Object.entries(CITY_COUNTRY.map)) { if (out.length >= limit) return; if (test(k) && !seen.has(v[0])) { seen.add(v[0]); out.push(v); } } };
  add(k => k.startsWith(t));
  add(k => k.split(/[\s-]/).some(w => w.startsWith(t)));
  return out;
}
/* описание варианта (od) — мелкой строкой под ним */
const optDesc = (q, o) => (q && q.od && q.od[plainLabel(o)]) || '';
/* вопрос показываем, если выполнено условие showIf (ответ на другой вопрос — из списка) */
function qVisible(q, answers) {
  if (q.auto) return false;
  if (!q.showIf) return true;
  const v = answers[q.showIf.id];
  const vals = Array.isArray(v) ? v : v ? [v] : [];
  return vals.some(x => q.showIf.o.includes(plainLabel(x)));
}
/* варианты этапа жизни под выбранную сферу (dep); без сферы — все */
function depOptions(q, answers) {
  if (!q.dep) return q.o.map((o, i) => i);
  const groups = q.dep.map[plainLabel(answers[q.dep.id] || '')];
  return q.o.map((o, i) => i).filter(i => !groups || groups.includes(q.g[i]));
}
/* группы этапа жизни (для сегментов статистики): этапов можно выбрать два — групп тоже до двух;
   старые подписи переводим в новые */
function stageGroupsOf(answers) {
  const q = Q_DEFAULT.client.test.find(x => x.id === 'stage');
  const v = (answers || {}).stage;
  const out = [];
  (Array.isArray(v) ? v : v ? [v] : []).map(x => canonLabel(q, x)).forEach(x => { const i = q.o.indexOf(x); const g = i >= 0 ? q.gshort[q.g[i]] : ''; if (g && !out.includes(g)) out.push(g); });
  return out;
}
const stageGroupOf = answers => stageGroupsOf(answers)[0] || '';
/* правило подбора контента в Еве по уровню энергии (правки 13.10): 1–3 — только мягкий, 8–10 — интенсивный */
const ENERGY_RULE = [
  {max: 3, name: 'Только мягкий контент', text: 'дыхание, медитации, сон и бережное восстановление — без нагрузок и челленджей'},
  {max: 7, name: 'Обычный режим', text: 'умеренные практики, нагрузку добавлять постепенно'},
  {max: 10, name: 'Можно интенсивный контент', text: 'активные практики, спорт, челленджи и программы с нагрузкой'},
];
const energyRule = v => { const x = Number(v); return x >= 1 ? ENERGY_RULE.find(r => x <= r.max) || null : null; };
/* цвет деления шкалы: от красного к зелёному */
function scaleHue(i, n) { return Math.round(4 + (i - 1) / Math.max(1, n - 1) * 128); }

/* подпись варианта для подсчёта: без смайлов, старые подписи — как новые,
   «Другое: свой ответ» — просто «Другое» */
const plainLabel = s => String(s ?? '').replace(/[\p{Extended_Pictographic}\u{1F1E6}-\u{1F1FF}\u{1F3FB}-\u{1F3FF}\u200d\uFE0F\u20E3]/gu, '').replace(/\s{2,}/g, ' ').trim();
const OTHER_SEP = ': ';
function canonLabel(q, label) {
  const l = plainLabel(label);
  if (q && q.other && (l === q.other || l.startsWith(q.other + OTHER_SEP))) return q.other;
  if (q && q.alias && q.alias[l]) return q.alias[l];
  return l;
}
/* свой ответ из «Другое: …» */
function otherText(q, label) {
  const l = String(label ?? '');
  return q && q.other && l.startsWith(q.other + OTHER_SEP) ? l.slice(q.other.length + OTHER_SEP.length).trim() : '';
}
const scaleN = q => (q && Number(q.n) > 5 ? Number(q.n) : 5);

/* возраст из даты рождения; старые анкеты отвечали группой */
const AGE_GROUPS = ['до 25', '25–34', '35–44', '45+'];
function ageFromBirth(birth, now = new Date()) {
  const m = String(birth || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  let a = now.getFullYear() - Number(m[1]);
  if (now.getMonth() + 1 < Number(m[2]) || (now.getMonth() + 1 === Number(m[2]) && now.getDate() < Number(m[3]))) a--;
  return a >= 5 && a <= 110 ? a : null;
}
const ageGroup = a => (a === null || a === undefined ? null : a < 25 ? AGE_GROUPS[0] : a < 35 ? AGE_GROUPS[1] : a < 45 ? AGE_GROUPS[2] : AGE_GROUPS[3]);
function ageGroupOf(answers) {
  const a = answers || {};
  const g = ageGroup(ageFromBirth(a.birth));
  if (g) return g;
  const old = plainLabel(a.age || '');
  return AGE_GROUPS.includes(old) ? old : null;
}
